package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Collection;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerException;

/**
 * Rejects a create-owner request that would join an existing household, responding 409. The
 * household is keyed on last name and postcode (see {@link OwnerHouseholds}), so a second owner
 * with the same last name and postcode is a duplicate. The request can opt out of the block by
 * setting {@code sharesHousehold}: a declared household member is allowed through and is later
 * created as such (and is not treated as a suspected duplicate, see
 * {@link AssignOwnerPossibleDuplicate}).
 *
 * <p>Runs before {@link BuildOwner}, comparing the request's last name and postcode against the
 * existing owners; these fields are stored unchanged, so this matches what
 * {@link AssignOwnerHousehold} later stamps.
 */
public class RejectDuplicateOwnerHousehold {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateOwnerException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return; // a declared household member is allowed past the duplicate block
        }
        Collection<Owner> existing = ownerRepository.findAll();
        if (!OwnerHouseholds.members(existing, request.getLastName(), request.getPostcode()).isEmpty()) {
            throw new DuplicateOwnerException(
                    OwnerHouseholds.householdId(request.getLastName(), request.getPostcode()));
        }
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Records how many existing owners already share the built owner's first and last name,
 * compared case-insensitively. Runs after the owner is built but before it is saved, so the
 * count reflects the owners that existed before this create, and mutates the built
 * {@link Owner} in place.
 */
public class AssignOwnerNamesakeCount {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String firstName = canonical(owner.getFirstName());
        String lastName = canonical(owner.getLastName());
        int namesakes = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (firstName.equals(canonical(existing.getFirstName()))
                    && lastName.equals(canonical(existing.getLastName()))) {
                namesakes++;
            }
        }
        owner.setNamesakeCount(namesakes);
    }

    private static String canonical(String value) {
        return value == null ? "" : value.toLowerCase(Locale.ROOT);
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.Objects;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Flags a soft duplicate: a create that is not a hard duplicate (see
 * {@link RejectDuplicateOwnerHousehold}, which already let it through) but that shares an
 * existing owner's last name and postcode while carrying a <em>different</em> telephone. The
 * owner is still created; the response merely carries {@code possibleDuplicate}/
 * {@code possibleDuplicateOf} pointing at the matched owner.
 *
 * <p>A declared household member — one created with {@code sharesHousehold} — deliberately
 * shares an existing owner's last name and postcode, so it is <em>not</em> a suspected
 * duplicate and is left unflagged.
 *
 * <p>Runs after {@link BuildOwner} but before the owner is saved, so it compares against the
 * owners that existed before this create (and so never matches the owner being built), and
 * mutates the built {@link Owner} in place. When several owners match, the one with the lowest
 * id is reported, so the result is deterministic. Last names are compared case-insensitively
 * (as elsewhere, e.g. {@link AssignOwnerNamesakeCount}); postcode and telephone are compared in
 * their stored, normalized form.
 */
public class AssignOwnerPossibleDuplicate {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return; // a declared household member is not a suspected duplicate
        }
        String lastName = canonical(owner.getLastName());
        String postcode = trimmed(owner.getPostcode());
        String telephone = trimmed(owner.getTelephone());
        if (postcode == null) {
            return; // no postcode to share, so no soft match
        }
        Owner match = null;
        for (Owner existing : ownerRepository.findAll()) {
            if (lastName.equals(canonical(existing.getLastName()))
                    && postcode.equals(trimmed(existing.getPostcode()))
                    && !Objects.equals(telephone, trimmed(existing.getTelephone()))
                    && (match == null || existing.getId() < match.getId())) {
                match = existing;
            }
        }
        if (match != null) {
            owner.setPossibleDuplicateOf(match.getId());
        }
    }

    private static String canonical(String value) {
        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
    }

    private static String trimmed(String value) {
        if (value == null) {
            return null;
        }
        String trimmed = value.trim();
        return trimmed.isEmpty() ? null : trimmed;
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Records how many owners share the built owner's household — the owners with the same last
 * name and postcode (see {@link OwnerHouseholds}) — counting this owner as well. Runs after
 * {@link AssignOwnerHousehold} has stamped the id but before the owner is saved, so the count
 * reflects the household size after this create, and mutates the built {@link Owner} in place.
 */
public class AssignOwnerHouseholdSize {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        int size = 1 + OwnerHouseholds.members(ownerRepository.findAll(),
                owner.getLastName(), owner.getPostcode()).size();
        owner.setHouseholdSize(size);
    }
}

